<?php
require_once __DIR__.'/../config.php';require_admin();$pageTitle='Resource approvals';
if(is_post()){verify_csrf();$id=valid_id($_POST['id']??0);$action=$_POST['action']??'';$reason=posted_string('reject_reason',1000);$stmt=$pdo->prepare('SELECT id FROM resources WHERE id=?');$stmt->execute([$id]);if(!$stmt->fetch())set_flash('error','Resource not found.');elseif($action==='approve'){$pdo->prepare("UPDATE resources SET status='approved',reject_reason=NULL WHERE id=?")->execute([$id]);set_flash('success','Resource approved and published.');}elseif($action==='reject'){$pdo->prepare("UPDATE resources SET status='rejected',reject_reason=? WHERE id=?")->execute([$reason?:'Please review the resource and submit an improved version.',$id]);set_flash('success','Resource rejected with feedback.');}elseif($action==='delete'){$pdo->prepare('DELETE FROM resources WHERE id=?')->execute([$id]);set_flash('success','Resource deleted.');}redirect('resources.php'.(!empty($_GET['status'])?'?status='.urlencode($_GET['status']):''));}
$status=(string)($_GET['status']??'pending');$allowed=['pending','approved','rejected','all'];if(!in_array($status,$allowed,true))$status='pending';$sql="SELECT r.*,s.name subject_name,c.name category_name,u.name uploader FROM resources r JOIN subjects s ON s.id=r.subject_id JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.uploader_id";$args=[];if($status!=='all'){$sql.=' WHERE r.status=?';$args[]=$status;}$sql.=' ORDER BY r.created_at DESC';$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();require __DIR__.'/../includes/admin_header.php';?>
<div class="toolbar"><div class="filters"><?php foreach(['pending','approved','rejected','all'] as $s): ?><a class="btn <?= $status===$s?'btn-primary':'btn-outline' ?> btn-small" href="?status=<?= $s ?>"><?= ucfirst($s) ?></a><?php endforeach; ?></div><span class="small-muted"><?= count($rows) ?> resources</span></div>
<div class="table-wrap"><table class="data-table"><thead><tr><th>Resource</th><th>Subject / category</th><th>Uploader</th><th>Status</th><th>Review actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['title']) ?></strong><div class="small-muted"><?= e(excerpt($r['description'],110)) ?></div><?php if($r['reject_reason']): ?><div class="small-muted">Feedback: <?= e($r['reject_reason']) ?></div><?php endif; ?></td><td><?= e($r['subject_name']) ?><br><span class="small-muted"><?= e($r['category_name']) ?></span></td><td><?= e($r['uploader']) ?></td><td><?= badge($r['status']) ?></td><td><div class="content-stack"><a class="btn btn-outline btn-small" href="../uploads/resources/<?= e(basename($r['file_path'])) ?>" target="_blank" rel="noopener">Open file</a><?php if($r['status']!=='approved'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="approve"><button class="btn btn-primary btn-small">Approve</button></form><?php endif; ?><?php if($r['status']!=='rejected'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="reject"><input name="reject_reason" placeholder="Reason (optional)"><button class="btn btn-outline btn-small">Reject</button></form><?php endif; ?><form method="post" data-confirm="Delete this resource and its database record?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div>
<?php require __DIR__.'/../includes/admin_footer.php';?>
